PROFILE_ROOT = Path(__PROFILE_ROOT__).expanduser()
PROFILES_INI = Path(__PROFILES_INI__).expanduser()

EVENTS_SQL = """
SELECT cal_id, id, title, event_start, event_end, event_start_tz, event_end_tz,
       last_modified, recurrence_id, recurrence_id_tz
FROM cal_events
ORDER BY event_start
"""

PROPERTIES_SQL = """
SELECT item_id, key, CAST(value AS TEXT) AS value, recurrence_id,
       recurrence_id_tz, cal_id
FROM cal_properties
"""

ALARMS_SQL = """
SELECT cal_id, item_id, recurrence_id, recurrence_id_tz, icalString
FROM cal_alarms
"""

RECURRENCE_SQL = """
SELECT item_id, cal_id, icalString
FROM cal_recurrence
"""


def profiles_ini_entries(path):
    entries = []
    if not path.is_file():
        return entries
    section = ""
    for raw_line in path.read_text(encoding="utf-8", errors="replace").splitlines():
        line = raw_line.strip()
        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1]
        elif "=" in line and section:
            key, _, value = line.partition("=")
            entries.append((section, key.strip(), value.strip()))
    return entries


def calendar_names(profile_path):
    # cal_metadata is empty in this Thunderbird build; the calendar display
    # names live in prefs.js as calendar.registry.<cal_id>.name.
    names = {}
    prefs = Path(profile_path) / "prefs.js"
    if not prefs.is_file():
        return names
    text = prefs.read_text(encoding="utf-8", errors="replace")
    pattern = re.compile(r'user_pref\("calendar\.registry\.([^.]+)\.name",\s*"(.*?)"\);')
    for match in pattern.finditer(text):
        names[match.group(1)] = match.group(2)
    return names


def read_calendar(db_path):
    # Snapshot sqlite + wal + shm into a temp dir and read the copy read-only:
    # a live Thunderbird keeps recent rows in local.sqlite-wal, so this matches
    # the recorded host_temporary_copy_of_guest_sqlite_wal read without writing
    # to the profile.
    result = {
        "event_row_count": 0,
        "events": [],
        "properties": [],
        "alarms": [],
        "recurrence": [],
        "calendar_error": None,
        "copied_files": [],
        "temporary_copy_removed": False,
    }
    tmpdir = Path(tempfile.mkdtemp(prefix="tbcal-"))
    try:
        db_path = Path(db_path)
        for suffix in ("", "-wal", "-shm"):
            source = Path(str(db_path) + suffix)
            if source.is_file():
                target = tmpdir / (db_path.name + suffix)
                shutil.copy2(str(source), str(target))
                result["copied_files"].append({
                    "filename": target.name,
                    "remote_path": str(source),
                    "copied": True,
                    "size": source.stat().st_size,
                })
        connection = sqlite3.connect("file:" + str(tmpdir / db_path.name) + "?mode=ro", uri=True)
        connection.row_factory = sqlite3.Row
        try:
            events = [dict(row) for row in connection.execute(EVENTS_SQL)]
            result["event_row_count"] = len(events)
            for event in events:
                event.setdefault("location", None)
                event.setdefault("description", None)
                event.setdefault("categories", None)
            result["events"] = events
            result["properties"] = [dict(row) for row in connection.execute(PROPERTIES_SQL)]
            result["alarms"] = [dict(row) for row in connection.execute(ALARMS_SQL)]
            result["recurrence"] = [dict(row) for row in connection.execute(RECURRENCE_SQL)]
        except sqlite3.Error as exc:
            result["calendar_error"] = "%s: %s" % (type(exc).__name__, exc)
        finally:
            connection.close()
    except OSError as exc:
        result["calendar_error"] = "%s: %s" % (type(exc).__name__, exc)
    finally:
        shutil.rmtree(str(tmpdir), ignore_errors=True)
        result["temporary_copy_removed"] = not tmpdir.exists()
    return result


entries = profiles_ini_entries(PROFILES_INI)
data_root = PROFILES_INI.parent
candidates = []
seen = set()


